// DecodeSearchRequest returns a decoder for requests sent to the featureflag
// search endpoint.
func DecodeSearchRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*featureflag.SearchPayload, error) {
	return func(r *http.Request) (*featureflag.SearchPayload, error) {
		var (
			query  string
			limit  uint
			offset uint
			err    error
		)
		qp := r.URL.Query()
		query = qp.Get("query")
		if query == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("query", "query string"))
		}
		if utf8.RuneCountInString(query) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("query", query, utf8.RuneCountInString(query), 1, true))
		}
		if utf8.RuneCountInString(query) > 100 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("query", query, utf8.RuneCountInString(query), 100, false))
		}
		{
			limitRaw := qp.Get("limit")
			if limitRaw == "" {
				limit = 10
			} else {
				v, err2 := strconv.ParseUint(limitRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("limit", limitRaw, "unsigned integer"))
				}
				limit = uint(v)
			}
		}
		if limit > 100 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("limit", limit, 100, false))
		}
		{
			offsetRaw := qp.Get("offset")
			if offsetRaw != "" {
				v, err2 := strconv.ParseUint(offsetRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("offset", offsetRaw, "unsigned integer"))
				}
				offset = uint(v)
			}
		}
		if err != nil {
			return nil, err
		}
		payload := NewSearchPayload(query, limit, offset)

		return payload, nil
	}
}

